  function schedule() {
    if (state.timer) clearTimeout(state.timer);
    state.timer = setTimeout(poll, state.pollMs);
  }

  function startUpdates() {
    state.pollMs = POLL_FAST_MS;
    schedule();
    openSocket();
  }

  function stopUpdates() {
    if (state.timer) clearTimeout(state.timer);
    state.timer = null;
    if (state.socket) {
      state.socket.onclose = null;
      state.socket.close();
      state.socket = null;
    }
  }

